// Route API example (Node.js/Express)
app.get('/api/teachers/:id/dashboard-stats', async (req, res) => {
  try {
    const teacherId = req.params.id;
    
    // Récupérer les statistiques depuis la base de données
    const coursesCount = await Course.count({ where: { teacherId } });
    const studentsCount = await StudentCourse.count({ 
      where: { 
        courseId: { 
          [Op.in]: await Course.findAll({ where: { teacherId }, attributes: ['id'] }) 
        } 
      } 
    });
    const pendingAssignments = await Assignment.count({ 
      where: { 
        courseId: { 
          [Op.in]: await Course.findAll({ where: { teacherId }, attributes: ['id'] }) 
        },
        status: 'pending'
      } 
    });
    
    // Calcul du taux de réussite
    const successRate = await calculateSuccessRate(teacherId);

    res.json({
      coursesCount,
      studentsCount,
      pendingAssignments,
      successRate
    });
  } catch (error) {
    res.status(500).json({ error: "Erreur serveur" });
  }
});
